//! Chess960 starting positions, generated by shakmaty's Scharnagl decoder.

use shakmaty::{
    fen::Fen, Board, CastlingMode, Chess, Color, EnPassantMode, FromSetup, Role, Setup,
};

/// The 960 Scharnagl starting positions as six-field FENs.
pub fn scharnagl_starts() -> Vec<String> {
    (0..960)
        .filter_map(|n| {
            let board = Board::chess960(n);
            let mut setup = Setup::empty();
            setup.board = board;
            setup.turn = Color::White;
            // Both rooks on each back rank hold castling rights in a start position.
            setup.castling_rights = setup.board.by_role(Role::Rook);
            let chess = Chess::from_setup(setup, CastlingMode::Chess960).ok()?;
            Some(Fen::from_position(&chess, EnPassantMode::Legal).to_string())
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn nine_sixty_starts() {
        let v = scharnagl_starts();
        assert_eq!(v.len(), 960, "got {}", v.len());
        for f in &v {
            assert!(
                Fen::from_ascii(f.as_bytes())
                    .ok()
                    .and_then(|x| x.into_position::<Chess>(CastlingMode::Chess960).ok())
                    .is_some(),
                "bad fen: {f}"
            );
        }
        let mut unique = v.clone();
        unique.sort();
        unique.dedup();
        assert_eq!(unique.len(), 960, "positions must be distinct");
    }

    #[test]
    fn standard_start_included() {
        let v = scharnagl_starts();
        assert!(v.iter().any(|f| f.starts_with("rnbqkbnr/pppppppp")));
    }
}
